insert into biz_stored_value_log (member_id, amount_type, change_amount,
    principal_after, gift_after, ref_no, create_by, create_time, remark)
select #{memberId}, #{amountType}, #{changeAmount},
       b.principal_balance, b.gift_balance, #{refNo}, '', now(), #{remark}
from biz_member_balance b where b.member_id = #{memberId}
